cd /tmp/friends-main && python3 - <<'PY'
import subprocess,re
branches=['rachel','monica','phoebe','joey','chandler','ross']
shas=set()
for b in branches:
    for sha in subprocess.check_output(['git','log','--format=%H',f'origin/friend/{b}'],text=True).split():
        msg=subprocess.check_output(['git','log','-1','--format=%B',sha],text=True)
        if 'Friend-Message: 1' in msg.splitlines():
            shas.add(sha)
src=set()
loc={}
for f in subprocess.check_output(['git','ls-tree','-r','--name-only','origin/main'],text=True).split():
    if not (f.startswith('S') and '/E' in f and f.endswith('.md')): continue
    c=subprocess.check_output(['git','show',f'origin/main:{f}'],text=True)
    for m in re.finditer(r'^Source: friend/\S+ @ ([0-9a-f]{40})$',c,re.M):
        src.add(m.group(1)); loc[m.group(1)]=f
extra=src-shas
print('extra sources:',len(extra))
for e in extra:
    print(e, loc[e])
    # show commit
    try:
        print(subprocess.check_output(['git','log','-1','--format=%s',e],text=True).strip())
    except Exception as ex:
        print('no commit',ex)
